import {COUNTRIES,IDS,CATEGORIES,KINDS,COALITIONS,uid,now,nameOf,flag,seed,validateStatement,resolve,eligible,forecast,tally,toCSV,validateBackup,validateAnalysis,evidenceValid} from './core.js';
import {openDB,readDB,saveDB,audit,backup,restore} from './db.js';
import {mountMap,legendHTML} from './map.js';
import {extractFile,parseImport,validateImport} from './imports.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(pairs,value)=>pairs.map(([v,label])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('');
const countryOptions=value=>options(COUNTRIES.map(c=>[c.id,c.name]).sort((a,b)=>a[1].localeCompare(b[1])),value);
const categoryOptions=value=>options(Object.entries(CATEGORIES).map(([k,v])=>[k,v[0]]),value);
const button=(label,act,id='',cls='')=>`<button class="${cls}" data-act="${act}" data-id="${esc(id)}">${label}</button>`;
const badge=(category,status='')=>`<span class="badge"><i style="background:${CATEGORIES[category]?.[1]||'#859baa'}"></i>${esc(CATEGORIES[category]?.[0].split(' / ')[0]||category)}${status?' · '+esc(status):''}</span>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-symbol">◎</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
const heading=(eyebrow,title,sub,actions='')=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;
const navItems=[['overview','◫','Overview'],['map','◎','World Map'],['countries','⚑','Countries'],['statements','▤','Statements'],['proposals','◇','Proposals'],['alliances','⌘','Alliances'],['timeline','◷','Timeline'],['settings','⚙','Settings']];
let state,activeMap,renderVersion=0,ownerToken='',busy=false;
let mapView=null;
let filters={perspective:'GBR',selected:'GBR',mode:'relationship',proposal:'diego-garcia',only:'all',participants:false,tentative:false,from:'',to:'',week:'',markers:true,overlay:false};
let statementFilter={country:'',week:'',query:'',from:'',to:'',archived:false};let countryFilter={query:''};let timelineFilter={country:'',from:'',to:''};let sort={countries:{key:'name',dir:1},statements:{key:'date',dir:-1}};let bulkRows=[];
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('atlas-changes'):null;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.style.background=error?'#512d36':'#20483e';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),6500);}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#close-modal').onclick=closeModal;
async function mutate(action,id,fn){const work=async()=>{const fresh=await readDB();const next=structuredClone(fresh);await fn(next);audit(next,action,id);await saveDB(next);state=next;channel?.postMessage('changed');};if(navigator.locks)await navigator.locks.request('atlas-write',work);else await work();await render();}
channel&&(channel.onmessage=async()=>{state=await readDB();if(!$('#modal').open)render();});
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function latestAnalysis(s){return state.analyses.filter(a=>a.statementId===s.id&&a.sourceRevision===s.revision).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];}
function countryStatements(id){return state.statements.filter(s=>s.country===id&&!s.deleted).sort((a,b)=>b.date.localeCompare(a.date));}
function sourceLink(s){return s.url&&/^https?:\/\//i.test(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Original publication ↗</a>`:'';}
function recordCard(s){const a=latestAnalysis(s);return `<div class="record"><div class="meta"><span>${flag(s.country)} ${esc(nameOf(s.country))}</span><span>· ${esc(s.week)} · ${esc(s.date)}</span><span>${s.archived?'Archived':''}</span></div><h3>${button(esc(s.title),'statement',s.id,'linklike')}</h3>${a?`<ul class="summary">${a.summary.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>${a.origin==='manual'?'Manual summary':'AI interpretation'} · ${a.reviewed?'Reviewed':'Awaiting review'}</small>`:'<p>No summary yet. Add a manual review or run AI analysis.</p>'}</div>`;}
function mapFilters(full){return `<div class="filters"><label>View diplomatic relations from<select data-map="perspective">${countryOptions(filters.perspective)}</select></label><label>Map perspective<select data-map="mode">${options([['relationship','Diplomatic relationships'],['proposal','Positions on a proposal'],['coalition','Alliances & cooperation']],filters.mode)}</select></label>${filters.mode==='proposal'?`<label>Selected proposal<select data-map="proposal">${options(state.proposals.map(p=>[p.id,p.title]),filters.proposal)}</select></label>`:''}<label>Show<select data-map="only">${options([['all','All orientations'],['support','Strong support only'],['opposition','Opposition & tensions'],['unknown','Unknown positions']],filters.only)}</select></label>${full?`<label>From date<input type="date" data-map="from" value="${esc(filters.from)}"></label><label>Through date<input type="date" data-map="to" value="${esc(filters.to)}"></label><label>Week / session<select data-map="week">${options([['','All weeks'],...[...new Set(state.statements.map(s=>s.week))].map(w=>[w,w])],filters.week)}</select></label>`:''}<label class="check"><input type="checkbox" data-map="tentative" ${filters.tentative?'checked':''}> Include tentative assessments</label>${full?`<label class="check"><input type="checkbox" data-map="participants" ${filters.participants?'checked':''}> Dim nonparticipants</label><label class="check"><input type="checkbox" data-map="markers" ${filters.markers?'checked':''}> Geographic markers</label><label class="check"><input type="checkbox" data-map="overlay" ${filters.overlay?'checked':''}> Coalition overlay</label>`:''}</div>`;}
function countryPanel(id){const c=COUNTRIES.find(c=>c.id===id);if(!c)return `<aside class="map-panel"><span class="eyebrow">GEOGRAPHIC CONTEXT</span><h2>${esc(id==='ECU'?'Ecuador':(filters.selectedName||nameOf(id)))}</h2><p class="muted">Not one of the 23 participating delegations.</p>${id==='ECU'?'<p>Beanstalk crisis location. Official scenario, pp. 11–13.</p>':''}${button('Close panel','close-panel','','small')}</aside>`;const r=resolve(state,id,filters.mode==='proposal'?'proposal':filters.mode==='coalition'?'coalition':'relationship',filters.mode==='proposal'?filters.proposal:filters.perspective,filters);const statements=countryStatements(id),a=statements.length?latestAnalysis(statements[0]):null;return `<aside class="map-panel">${button('×','close-panel','','small quiet close-panel')}<span class="flag">${flag(id)}</span><h2>${esc(c.name)}</h2><small>${id==='GBR'?'YOUR DELEGATION':'PARTICIPATING DELEGATION'} · ${id}</small>${badge(r.category)}<p class="subtitle">${filters.mode==='proposal'?'Position on selected proposal':`${esc(c.name)} → ${esc(nameOf(filters.perspective))}`}</p><p class="subtitle">${esc(r.status)}${r.confidence!==null?' · '+Math.round(r.confidence*100)+'% confidence':''}</p>${r.locked?'<p class="lock-note">Locked manual confirmation</p>':''}<hr class="divider"><span class="eyebrow">LATEST STATEMENT SUMMARY</span>${a?`<ul class="summary">${a.summary.map(l=>`<li>${esc(l)}</li>`).join('')}</ul><small>${a.origin==='manual'?'Manual':'AI'} · ${a.reviewed?'Reviewed':'Unreviewed'} interpretation</small>`:'<p class="muted">No analyzed statement. Positions remain unknown until evidence is recorded.</p>'}${r.rows.slice(0,2).map(a=>`<blockquote>${esc(a.quote)}</blockquote>${button('View evidence','evidence',a.id,'small quiet')}`).join('')}<hr class="divider"><p class="subtitle">${statements.length} statements in archive</p><a class="button small" href="#country/${id}">Open full profile ↗</a></aside>`;}
function mapSection(full=false){return `<section class="panel ${full?'map-page':''}"><div class="panel-head"><h2>Diplomatic landscape</h2><span class="eyebrow">23 ACTIVE DELEGATIONS</span></div>${mapFilters(full)}<div class="map-layout"><div id="world-map" class="map" aria-label="Interactive world map"></div>${filters.selected?countryPanel(filters.selected):''}</div><div class="legend">${legendHTML()}</div><div class="map-note">TURQUOISE OUTLINE · PARTICIPANT &nbsp; / &nbsp; BRIGHT OUTLINE · SELECTED &nbsp; / &nbsp; FILLS · ${filters.tentative?'APPROVED + TENTATIVE':'APPROVED EVIDENCE ONLY'}</div></section>`;}
function overview(){const current=COUNTRIES.filter(c=>c.id!=='GBR').map(c=>resolve(state,c.id,'relationship','GBR'));const known=current.filter(r=>r.category!=='unknown').length;const pending=state.assessments.filter(a=>a.status==='tentative'&&evidenceValid(a,state)).length;const statements=state.statements.filter(s=>!s.deleted);return heading('YOUR DIPLOMATIC COMMAND CENTER','The world, in perspective.','Track positions. Read the evidence. Shape the next conversation.',button('＋ Add statement','new-statement','','primary'))+`<div class="stats"><div class="stat"><span class="label">Active delegations</span><strong>23</strong><small>United Kingdom perspective</small></div><div class="stat"><span class="label">Statements recorded</span><strong>${statements.length}</strong><small>${new Set(statements.map(s=>s.week)).size} sessions in your archive</small></div><div class="stat"><span class="label">Known relationships</span><strong>${known}<em>/ 22</em></strong><small>${22-known} remain unknown toward the UK</small></div><div class="stat"><span class="label">Awaiting review</span><strong style="color:var(--orange)">${pending}</strong><small>Evidence awaiting your confirmation</small></div></div>`+mapSection()+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Latest delegation statements</h2><a href="#statements">View archive ↗</a></div>${statements.length?statements.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(recordCard).join(''):empty('Your intelligence starts here','Add a weekly statement, review its analysis, and watch the diplomatic picture take shape.',button('Add your first statement','new-statement','','small'))}</section><section class="panel"><div class="panel-head"><h2>Crisis brief</h2><span class="badge warn">OFFICIAL SCENARIO</span></div><div class="record"><div class="meta">20 OCTOBER 2050 · ECUADOR</div><h3>Beanstalk under siege</h3><p>El Frente por la Restauración de la Sierra has seized the Chimborazo space elevator project. Approximately 500 GALSIM personnel are held hostage.</p><small>Scenario, pp. 11–12 · Fictional course canon</small></div><div class="record"><div class="meta">UK INITIATIVE · USER-SUPPLIED</div><h3>A second elevator on Diego Garcia</h3><p>A separate UK proposal. No other delegation’s position has been assumed.</p><a href="#proposals">Explore proposal →</a></div></section></div>`;}
function sorted(rows,section){const {key,dir}=sort[section];return rows.sort((a,b)=>String(a[key]??'').localeCompare(String(b[key]??''),undefined,{numeric:true})*dir);}
function th(label,key,section){return `<th><button data-sort="${section}" data-key="${key}">${label} ${sort[section].key===key?(sort[section].dir===1?'↑':'↓'):'↕'}</button></th>`;}
function countriesView(){const rows=sorted(COUNTRIES.map(c=>({...c,orientation:resolve(state,c.id,'relationship',filters.perspective).category,count:countryStatements(c.id).length})).filter(c=>`${c.name} ${c.id}`.toLowerCase().includes(countryFilter.query.toLowerCase())),'countries');return heading('DELEGATION DIRECTORY','Countries','23 voices. Every position grounded in a source.',button('Export CSV','countries-csv','','quiet'))+`<section class="panel"><div class="filters"><label>Search countries<input data-country-filter="query" value="${esc(countryFilter.query)}" placeholder="Country name or ISO code"></label><label>Relationships toward<select data-map="perspective">${countryOptions(filters.perspective)}</select></label><span class="filter-count">${rows.length} delegations</span></div><div class="table-wrap"><table><thead><tr>${th('Delegation','name','countries')}${th('ISO-3','id','countries')}${th('Orientation','orientation','countries')}${th('Statements','count','countries')}</tr></thead><tbody>${rows.map(c=>`<tr><td><div class="country-cell"><span class="flag">${flag(c.id)}</span><a href="#country/${c.id}">${esc(c.name)}</a></div></td><td class="muted">${c.id}</td><td>${badge(c.orientation)}</td><td>${c.count}</td></tr>`).join('')}</tbody></table></div></section>`;}
function assessmentsHTML(rows){return rows.length?rows.map(a=>{const s=state.statements.find(s=>s.id===a.statementId);return `<div class="record"><div class="meta">${esc(nameOf(a.country))} → ${esc(a.kind==='proposal'?state.proposals.find(p=>p.id===a.target)?.title:nameOf(a.target))} · ${esc(KINDS[a.kind])}</div>${badge(a.category,a.status)}<blockquote>${esc(a.quote)}</blockquote><p>${esc(a.interpretation)}</p><small>${esc(s?.date)} · ${esc(s?.title)} · ${Math.round(a.confidence*100)}% · ${a.explicit?'Explicit':'Inferred'} · ${esc(a.origin||'AI interpretation')}${a.locked?' · LOCKED':''}${!evidenceValid(a,state)?' · HISTORICAL / INVALIDATED SOURCE REVISION':''}</small>${button('Inspect / review','evidence',a.id,'small quiet spaced')}</div>`}).join(''):empty('No evidence recorded','Relationships and proposal positions remain unknown.');}
function profile(id){if(!IDS.includes(id))return heading('COUNTRY','Country not found','Choose a participating delegation.');const statements=countryStatements(id),latest=statements[0],a=latest&&latestAnalysis(latest);const relations=eligible(state).filter(r=>r.country===id&&r.kind!=='proposal');return heading('DELEGATION PROFILE',`${flag(id)} ${esc(nameOf(id))}`,'Source-backed positions and the complete statement archive.',button('Export country','country-export',id)+button('＋ Add statement','new-statement',id,'primary'))+`<section class="panel pad"><div class="profile-hero"><div class="flag">${flag(id)}</div><div><h2>${esc(nameOf(id))}</h2><span class="badge accent">${id==='GBR'?'YOUR DELEGATION':'ACTIVE DELEGATION'} · ${id}</span></div></div><div class="spaced">${a?`<ul class="summary">${a.summary.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>Latest-statement overview · ${a.origin==='manual'?'Manual':'AI'} · ${a.reviewed?'Reviewed':'Unreviewed'} · ${esc(latest.date)}</small>`:'<p class="muted">No country overview is available until a statement is analyzed or summarized.</p>'}</div><div class="actions"><span>Relationship toward UK:</span>${badge(resolve(state,id,'relationship','GBR').category)}<span>Toward ${esc(nameOf(filters.perspective))}:</span>${badge(resolve(state,id,'relationship',filters.perspective).category)}<select data-map="perspective" aria-label="Profile perspective">${countryOptions(filters.perspective)}</select></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Statement archive · ${statements.length}</h2></div>${statements.length?statements.map(recordCard).join(''):empty('No statements yet','Add this delegation’s weekly publications to begin tracking its position.')}</section><div><section class="panel"><div class="panel-head"><h2>Proposal positions</h2></div>${state.proposals.map(p=>`<div class="record"><h3><a href="#proposal/${esc(p.id)}">${esc(p.title)}</a></h3>${badge(resolve(state,id,'proposal',p.id).category)}</div>`).join('')}</section><section class="panel spaced"><div class="panel-head"><h2>Confirmed relationships & cooperation</h2></div>${assessmentsHTML(relations)}</section></div></div><section class="panel spaced"><div class="panel-head"><h2>Diplomatic evidence history</h2></div>${assessmentsHTML(state.assessments.filter(a=>a.country===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))}</section>`;}
function filteredStatements(){return state.statements.filter(s=>!s.deleted&&(statementFilter.archived||!s.archived)&&(!statementFilter.country||s.country===statementFilter.country)&&(!statementFilter.week||s.week===statementFilter.week)&&(!statementFilter.from||s.date>=statementFilter.from)&&(!statementFilter.to||s.date<=statementFilter.to)&&`${s.title} ${s.text} ${nameOf(s.country)}`.toLowerCase().includes(statementFilter.query.toLowerCase()));}
function statementsView(){const rows=sorted(filteredStatements().map(s=>({...s,countryName:nameOf(s.country),status:s.archived?'Archived':latestAnalysis(s)?.reviewed?'Reviewed':latestAnalysis(s)?'Awaiting review':'Unanalyzed'})),'statements');return heading('WEEKLY INTELLIGENCE','Statements','Original publications, concise summaries, and an auditable trail of evidence.',button('Bulk import','bulk-import')+button('Export CSV','statements-csv')+button('＋ Add statement','new-statement','','primary'))+`<section class="panel"><div class="filters"><label>Search<input data-statement-filter="query" value="${esc(statementFilter.query)}" placeholder="Search statement text"></label><label>Delegation<select data-statement-filter="country"><option value="">All delegations</option>${countryOptions(statementFilter.country)}</select></label><label>Week / session<select data-statement-filter="week">${options([['','All weeks'],...[...new Set(state.statements.map(s=>s.week))].map(w=>[w,w])],statementFilter.week)}</select></label><label>From<input type="date" data-statement-filter="from" value="${statementFilter.from}"></label><label>Through<input type="date" data-statement-filter="to" value="${statementFilter.to}"></label><label class="check"><input type="checkbox" data-statement-filter="archived" ${statementFilter.archived?'checked':''}> Include archived</label></div>${rows.length?`<div class="table-wrap"><table><thead><tr>${th('Delegation','countryName','statements')}${th('Title','title','statements')}${th('Week','week','statements')}${th('Publication date','date','statements')}${th('Review','status','statements')}<th></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${flag(s.country)} ${esc(nameOf(s.country))}</td><td>${button(esc(s.title),'statement',s.id,'linklike')}</td><td>${esc(s.week)}</td><td>${esc(s.date)}</td><td><span class="badge">${s.status}</span></td><td>${button('Open →','statement',s.id,'small quiet')}</td></tr>`).join('')}</tbody></table></div>`:empty('Build your weekly archive','Paste text, upload a TXT or PDF, or import multiple statements. Original wording stays intact.',button('Add statement','new-statement','','primary'))}</section>`;}
function statementForm(id='',country='GBR'){const s=state.statements.find(x=>x.id===id)||{country,week:'Week 1',date:'2050-11-01',title:'',text:'',url:'',notes:''};modal(id?'Edit statement':'Add a weekly statement',`<form id="statement-form" data-id="${esc(id)}"><div class="form-grid"><label>Delegation<select name="country">${countryOptions(s.country)}</select></label><label>Week / session<input name="week" required maxlength="80" value="${esc(s.week)}"></label><label>Fictional publication date<input type="date" name="date" required value="${esc(s.date)}"></label><label>Title<input name="title" required maxlength="300" value="${esc(s.title)}"></label><label class="full file-drop">Extract text from TXT / PDF<input id="statement-file" type="file" accept=".txt,.pdf"><small>Review extracted text and assignment. For multi-delegation PDFs, use Bulk import to split records. Scanned PDFs require OCR.</small></label><label class="full">Full original statement<textarea name="text" rows="10" maxlength="60000" required>${esc(s.text)}</textarea></label><label class="full">Original publication URL (optional)<input type="url" name="url" value="${esc(s.url)}"></label><label class="full">Notes<textarea name="notes" rows="2">${esc(s.notes)}</textarea></label></div>${id?'<p class="notice warn spaced">Editing creates a new revision and invalidates classifications tied to the previous text. Historical records and locked assessments are retained in the audit trail.</p>':''}<div class="form-status" id="form-status"></div><div class="form-actions"><button type="submit" name="mode" value="save">Save statement</button><button type="submit" name="mode" value="analyze" class="primary">Save & analyze →</button></div></form>`);$('#statement-file').onchange=async e=>{try{$('#form-status').textContent='Extracting text…';const text=await extractFile(e.target.files[0]);$('#statement-form [name=text]').value=text;$('#statement-form [name=notes]').value+='\nImported from '+e.target.files[0].name;$('#form-status').textContent='Text extracted. Review and correct it before saving.';}catch(e){$('#form-status').textContent=e.message;}};$('#statement-form').onsubmit=async e=>{e.preventDefault();const mode=e.submitter?.value;const fields=Object.fromEntries(new FormData(e.target));try{validateStatement(fields);const newId=id||uid();await mutate(id?'Revise statement':'Create statement',newId,d=>{const existing=d.statements.find(x=>x.id===id);if(existing){audit(d,'Previous statement revision',id,existing);Object.assign(existing,fields,{revision:existing.revision+1,updatedAt:now()});}else d.statements.push({...fields,id:newId,revision:1,createdAt:now(),updatedAt:now(),archived:false,deleted:false});});closeModal();if(mode==='analyze')await analyze(newId);else showStatement(newId);}catch(error){$('#form-status').textContent=error.message;}};}
function reviewCard(a){return `<div class="review-card" data-review="${esc(a.id)}"><div class="meta">${esc(KINDS[a.kind])} · ${esc(a.kind==='proposal'?state.proposals.find(p=>p.id===a.target)?.title:nameOf(a.target))}</div><blockquote>${esc(a.quote)}</blockquote><label>Interpretation<textarea data-field="interpretation" rows="2">${esc(a.interpretation)}</textarea></label><div class="review-controls"><select data-field="category" aria-label="Classification">${categoryOptions(a.category)}</select><select data-field="status" aria-label="Review status">${options([['tentative','Tentative'],['approved','Approved'],['rejected','Rejected']],a.status)}</select><label class="check"><input type="checkbox" data-field="locked" ${a.locked?'checked':''}> Lock approved position</label><label class="check"><input type="checkbox" data-field="resolvesConflict" ${a.resolvesConflict?'checked':''}> Acknowledge change / resolve conflict</label></div><small class="spaced">${Math.round(a.confidence*100)}% confidence · ${a.explicit?'Explicit':'Inferred'} · ${esc(a.origin)} · Source revision ${a.sourceRevision}</small>${button('Save review','save-review',a.id,'small primary spaced')}</div>`;}
function showStatement(id){const s=state.statements.find(x=>x.id===id&&!x.deleted);if(!s)return;const a=latestAnalysis(s),rows=state.assessments.filter(x=>x.statementId===id&&x.sourceRevision===s.revision);modal(s.title,`<div class="actions"><span class="badge accent">${flag(s.country)} ${esc(nameOf(s.country))}</span><span class="badge">${esc(s.week)} · ${esc(s.date)} · Revision ${s.revision}</span></div><div class="actions spaced">${button('Analyze with AI','analyze',id,'primary')}${button('Manual assessment','manual',id)}${button('Edit source','edit-statement',id)}${button(s.archived?'Unarchive':'Archive','archive',id)}${button('Delete','delete-statement',id,'danger')}</div><div id="analysis-status" class="form-status"></div><hr class="divider"><h3>${a?.origin==='manual'?'Manual summary':'AI summary'} ${a?.reviewed?'· Reviewed':''}</h3><textarea id="summary-edit" rows="4" placeholder="Enter exactly 3 or 4 nonempty lines">${esc(a?.summary.join('\n')||'')}</textarea><div class="actions spaced">${button('Save reviewed summary','save-summary',id)}${rows.length?button('Approve all classifications','approve-all',id):''}</div>${a?`<small class="spaced">${esc(a.model||'Manual entry')} · ${esc(a.createdAt)} · ${a.reviewed?'Reviewed':'Tentative AI interpretation'}</small>${a.topics?.length?`<p class="subtitle">Topics: ${esc(a.topics.join(', '))}</p>`:''}${a.uncertainties?.length?`<p class="notice warn spaced">${esc(a.uncertainties.join(' · '))}</p>`:''}${a.changes?.length?`<h3 class="spaced">AI-detected changes (review required)</h3>${a.changes.map(c=>`<blockquote>${esc(c.quote)}</blockquote><p>${esc(c.interpretation)}</p>${button('Previous source','statement',c.previousStatementId,'small')}`).join('')}`:''}`:''}<h3 class="spaced">Classifications & evidence</h3>${rows.length?rows.map(reviewCard).join(''):'<p class="muted">No classifications. AI and manual assessments appear here before they affect the map.</p>'}<h3 class="spaced">Original statement</h3><div class="source-text">${esc(s.text)}</div><p>${sourceLink(s)}</p>${s.notes?`<p class="muted">Notes: ${esc(s.notes)}</p>`:''}<details><summary>Revision and analysis history</summary>${state.audit.filter(x=>x.entity===id&&x.before).map(x=>`<h3>Source revision ${x.before.revision} · ${esc(x.at)}</h3><div class="source-text">${esc(x.before.text)}</div>`).join('')}${state.analyses.filter(x=>x.statementId===id).map(x=>`<div class="record"><small>${esc(x.createdAt)} · ${esc(x.model||x.origin)} · source revision ${x.sourceRevision}</small><ul class="summary">${x.summary.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div>`).join('')}</details>`);}
async function analyze(id){if(busy)return toast('Another statement is already being analyzed.');const s=state.statements.find(x=>x.id===id);if(!s)return;busy=true;showStatement(id);$('#analysis-status').textContent='Analyzing source evidence… This can take a minute.';$$('[data-act=analyze]').forEach(b=>b.disabled=true);const previous=countryStatements(s.country).filter(p=>p.id!==id&&p.date<=s.date).slice(0,8);try{const response=await fetch(new URL('api/analyze',document.baseURI),{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${ownerToken}`},body:JSON.stringify({statement:s,proposals:state.proposals.map(p=>({id:p.id,title:p.title,description:p.description||''})),previous}),signal:AbortSignal.timeout(100000)});let data;try{data=await response.json();}catch{throw Error('AI endpoint unavailable on this static host. Run npm start with server configuration, or use the Cloudflare Worker deployment.');}if(!response.ok)throw Error(data.error||'Analysis failed.');validateAnalysis(data.analysis,s,state.proposals,previous);await mutate('Analyze statement',id,d=>{const current=d.statements.find(x=>x.id===id);if(current.revision!==s.revision||current.deleted)throw Error('Source changed during analysis. Please retry.');const analysisId=uid();d.analyses.push({...data.analysis,id:analysisId,sourceRevision:s.revision,createdAt:now(),model:data.model,origin:'AI',reviewed:false});for(const row of data.analysis.assessments)d.assessments.push({...row,id:uid(),country:s.country,statementId:id,analysisId,sourceRevision:s.revision,createdAt:now(),status:'tentative',origin:'AI interpretation',locked:false,resolvesConflict:false});});showStatement(id);toast('Analysis ready. Review before applying it to the map.');}catch(e){if($('#analysis-status'))$('#analysis-status').textContent=e.message;toast(e.message,true);}finally{busy=false;$$('[data-act=analyze]').forEach(b=>b.disabled=false);}}
function manualForm(id){const s=state.statements.find(x=>x.id===id);modal('Add an evidence-backed assessment',`<form id="manual-form"><p class="notice">This is a manual diplomatic assessment of ${esc(nameOf(s.country))}. Copy an exact passage from the source; approval is explicit.</p><div class="form-grid"><label>Assessment type<select name="kind" id="manual-kind">${options(Object.entries(KINDS),'relationship')}</select></label><label>Target<select name="target" id="manual-target">${countryOptions('GBR')}</select></label><label>Classification<select name="category">${categoryOptions('unknown')}</select></label><label>Coalition type (for cooperation records)<select name="coalitionType">${options(COALITIONS.map(x=>[x,x.replaceAll('_',' ')]),'formal_cooperation')}</select></label><label class="full">Exact supporting passage<textarea name="quote" required rows="3"></textarea></label><label class="full">Your interpretation<textarea name="interpretation" rows="2" required></textarea></label><label>Confidence (0–100)<input name="confidence" type="number" min="0" max="100" value="90" required></label><label>Review status<select name="status">${options([['tentative','Tentative'],['approved','Approved']],'tentative')}</select></label><label class="check"><input name="explicit" type="checkbox" checked> Explicit statement</label><label class="check"><input name="locked" type="checkbox"> Lock confirmed classification</label></div><details><summary>Read source text</summary><div class="source-text">${esc(s.text)}</div></details><div id="form-status" class="form-status"></div><div class="form-actions"><button class="primary">Save assessment</button></div></form>`);$('#manual-kind').onchange=e=>$('#manual-target').innerHTML=e.target.value==='proposal'?options(state.proposals.map(p=>[p.id,p.title]),filters.proposal):countryOptions('GBR');$('#manual-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!s.text.includes(f.quote)||!f.quote.trim())return $('#form-status').textContent='The quote must match an exact passage in the source.';if(f.kind!=='proposal'&&f.target===s.country)return $('#form-status').textContent='Choose a different target country.';await mutate('Manual assessment',id,d=>{d.assessments.push({...f,id:uid(),country:s.country,statementId:id,sourceRevision:s.revision,createdAt:now(),confidence:Number(f.confidence)/100,explicit:f.explicit==='on',locked:f.locked==='on'&&f.status==='approved',resolvesConflict:false,origin:'Manual assessment'});});showStatement(id);};}
function proposalSummary(p){const f=forecast(state,p.id);return `<div class="record"><div class="meta">${flag(p.country)} ${esc(nameOf(p.country))} · ${esc(p.status)} · ${esc(p.date||'Date not entered')}</div><h3><a href="#proposal/${esc(p.id)}">${esc(p.title)}</a></h3><p>${esc(p.description)}</p><div class="actions">${badge('strong_support',f.yes+' delegations')}${badge('strong_opposition',f.no+' delegations')}<span class="badge">${f.uncertain} unresolved / conditional</span></div><small class="spaced">${esc(p.origin)} · Sponsorship does not imply a recorded vote.</small></div>`;}
function proposalsView(){return heading('POLICY & NEGOTIATION','Proposals','Track initiatives and positions separately from diplomatic relationships.',button('＋ New proposal','new-proposal','','primary'))+`<section class="panel">${state.proposals.map(proposalSummary).join('')}</section>`;}
function proposalView(id){const p=state.proposals.find(p=>p.id===id);if(!p)return heading('PROPOSAL','Not found','Choose a proposal.');const f=forecast(state,id);const votes=state.votes.filter(v=>v.proposalId===id);return heading('PROPOSAL INTELLIGENCE',esc(p.title),`${esc(nameOf(p.country))} · ${esc(p.origin)}`,button('Edit proposal','edit-proposal',id)+button('View on map','proposal-map',id)+button('Record vote','new-vote',id,'primary'))+`<div class="notice">${esc(p.description)}<br>Status: ${esc(p.status)} · Date: ${esc(p.date||'Not entered')} · Sponsors: ${p.sponsors.map(nameOf).map(esc).join(', ')}</div><div class="stats"><div class="stat"><span class="label">Strong support</span><strong>${f.yes}</strong><small>Approved statement evidence</small></div><div class="stat"><span class="label">Strong opposition</span><strong>${f.no}</strong><small>Approved statement evidence</small></div><div class="stat"><span class="label">Unresolved / conditional</span><strong>${f.uncertain}</strong><small>Never counted as abstentions</small></div><div class="stat"><span class="label">Possible yes range</span><strong>${f.minYes}–${f.maxYes}</strong><small>Assumes strong positions hold</small></div></div><section class="panel pad"><h2>Voting forecast · analytical scenarios</h2><p class="muted">This is a position-based projection, not a vote intention or recorded ballot. With all 23 voting yes/no, 16 affirmative votes are needed. If all ${f.uncertain} unresolved delegations vote no, the projection is ${f.yes}/23; if they all vote yes, it is ${f.maxYes}/23. Abstentions reduce the votes-expressed denominator. Conditional positions remain unresolved.</p><div class="progress-track"><span style="width:${100*f.yes/23}%;background:#15866d"></span><span style="width:${100*f.uncertain/23}%;background:#455664"></span><span style="width:${100*f.no/23}%;background:#e26772"></span></div><small>Rules arts. 2, 17, 19–20 · one vote per delegation · no veto · chair rulings take precedence</small></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>All 23 delegation positions</h2></div>${f.positions.map(r=>`<div class="record"><div class="actions"><a href="#country/${r.country}">${flag(r.country)} ${esc(nameOf(r.country))}</a>${badge(r.category)}</div>${r.rows.length?button('View evidence','evidence',r.rows[0].id,'small quiet spaced'):''}</div>`).join('')}</section><div><section class="panel"><div class="panel-head"><h2>Recorded ballots</h2></div>${votes.length?votes.map(v=>{const t=tally(v.ballots,v.type,v.qualified);return `<div class="record"><h3>${esc(v.title)}</h3><p>${esc(v.date)} · ${esc(v.type)} · ${t.yes} yes / ${t.no} no / ${t.abstain} abstain</p><span class="badge">${t.outcome}</span><p>Chair decision: ${esc(v.chairDecision||'Not recorded')}</p>${button('View / complete ballot','edit-vote',v.id,'small')}</div>`}).join(''):empty('No vote recorded','A forecast never becomes an actual ballot automatically.')}</section><section class="panel spaced"><div class="panel-head"><h2>Related statements</h2></div>${[...new Set(state.assessments.filter(a=>a.kind==='proposal'&&a.target===id).map(a=>a.statementId))].map(id=>state.statements.find(s=>s.id===id&&!s.deleted)).filter(Boolean).map(recordCard).join('')||empty('No statements linked','Add evidence for this proposal in statement review.')}</section></div></div>`;}
function proposalForm(id=''){const p=state.proposals.find(x=>x.id===id)||{country:'GBR',title:'',description:'',status:'Proposed',date:'',sponsors:['GBR']};modal(id?'Edit proposal':'Register a proposal',`<form id="proposal-form"><div class="form-grid"><label class="full">Title<input name="title" required maxlength="300" value="${esc(p.title)}"></label><label>Proposing delegation<select name="country">${countryOptions(p.country)}</select></label><label>Introduction date (leave blank if unknown)<input name="date" type="date" value="${esc(p.date)}"></label><label class="full">Description<textarea name="description" rows="4" maxlength="5000" required>${esc(p.description)}</textarea></label><label>Status<select name="status">${options(['Proposed','Working paper','Draft resolution','Adopted','Rejected','Withdrawn'].map(x=>[x,x]),p.status)}</select></label><label>Sponsors (1–5, Ctrl/Cmd to select)<select name="sponsors" multiple size="5">${COUNTRIES.map(c=>`<option value="${c.id}" ${p.sponsors.includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><p class="notice spaced">Procedural status must reflect an actual chair decision. Registering a proposal does not establish support by any country.</p><div id="form-status" class="form-status"></div><div class="form-actions"><button class="primary">Save proposal</button></div></form>`);$('#proposal-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd),sponsors=fd.getAll('sponsors');if(sponsors.length<1||sponsors.length>5)return $('#form-status').textContent='Select between one and five sponsors.';await mutate('Save proposal',id||f.title,d=>{const existing=d.proposals.find(x=>x.id===id);if(existing){audit(d,'Previous proposal version',id,existing);Object.assign(existing,f,{sponsors,updatedAt:now()});}else d.proposals.push({...f,sponsors,id:uid(),origin:'User-entered simulation proposal',createdAt:now()});});closeModal();};}
function voteForm(proposalId,id=''){const v=state.votes.find(v=>v.id===id)||{proposalId,type:'substantive',qualified:false,ballots:Object.fromEntries(IDS.map(c=>[c,'unknown'])),title:'Roll-call vote',date:'2050-11-01',source:'',chairDecision:''};modal('Record a committee vote',`<form id="vote-form"><div class="form-grid"><label>Title / document version<input name="title" required value="${esc(v.title)}"></label><label>Simulation date<input name="date" type="date" required value="${esc(v.date)}"></label><label>Vote type<select name="type" id="vote-type">${options([['substantive','Substantive — draft resolution'],['procedural','Procedural motion']],v.type)}</select></label><label class="check"><input type="checkbox" name="qualified" ${v.qualified?'checked':''}> Qualified procedural majority (2/3)</label><label class="full">Source / session record<input name="source" required value="${esc(v.source)}"></label><label class="full">Chair decision / rule override (optional)<input name="chairDecision" value="${esc(v.chairDecision)}"></label></div><div class="notice spaced">Substantive votes require 2/3 of yes + no, with at least 12 of 23 present. Abstentions do not count as votes expressed. A first-round pass must become yes/no in the next round. Procedural votes prohibit abstentions and passes.</div><div class="vote-grid">${COUNTRIES.map(c=>`<label>${flag(c.id)} ${esc(c.name)}<select data-ballot="${c.id}">${options([['unknown','Not recorded'],['yes','For / yes'],['no','Against / no'],['abstain','Abstention'],['pass','Pass — first round'],['absent','Absent']],v.ballots[c.id])}</select></label>`).join('')}</div><div id="vote-preview" class="notice"></div><div id="form-status" class="form-status"></div><div class="form-actions"><button class="primary">Save recorded ballot</button></div></form>`);const preview=()=>{try{const ballots=Object.fromEntries($$('[data-ballot]').map(x=>[x.dataset.ballot,x.value])),t=tally(ballots,$('#vote-type').value,$('[name=qualified]').checked);$('#vote-preview').textContent=`${t.yes} yes · ${t.no} no · ${t.abstain} abstain · ${t.pending} unresolved · provisional threshold ${t.threshold} · ${t.outcome}`;}catch(e){$('#vote-preview').textContent=e.message;}};$('#vote-form').onchange=preview;preview();$('#vote-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.qualified=f.qualified==='on';f.ballots=Object.fromEntries($$('[data-ballot]').map(x=>[x.dataset.ballot,x.value]));try{tally(f.ballots,f.type,f.qualified);for(const [c,b] of Object.entries(v.ballots))if(b==='pass'&&!['pass','yes','no'].includes(f.ballots[c]))throw Error(`${nameOf(c)} passed in round one and must now vote yes or no.`);await mutate('Record vote',id||proposalId,d=>{const existing=d.votes.find(x=>x.id===id);if(existing){audit(d,'Previous ballot',id,existing);Object.assign(existing,f,{updatedAt:now()});}else d.votes.push({...f,id:uid(),proposalId,createdAt:now()});});closeModal();}catch(e){$('#form-status').textContent=e.message;}};}
let networkFilter={country:'GBR',type:'all',connected:false,tentative:false};
function networkView(){const rows=eligible(state,{tentative:networkFilter.tentative}).filter(a=>a.kind!=='proposal'&&(networkFilter.type==='all'||a.coalitionType===networkFilter.type||a.kind===networkFilter.type));const links=rows.filter(a=>!networkFilter.country||a.country===networkFilter.country||a.target===networkFilter.country);const connected=new Set(links.flatMap(a=>[a.country,a.target]));if(networkFilter.country)connected.add(networkFilter.country);const nodes=COUNTRIES.filter(c=>!networkFilter.connected||connected.has(c.id));const positions=new Map(nodes.map((c,i)=>[c.id,{x:470+330*Math.cos(2*Math.PI*i/nodes.length-Math.PI/2),y:260+210*Math.sin(2*Math.PI*i/nodes.length-Math.PI/2)}]));return heading('DIPLOMATIC NETWORK','Alliances & relationships','Directional, source-backed connections. Shared votes are never automatic alliances.')+`<section class="panel"><div class="filters"><label>Highlight delegation<select data-network="country"><option value="">Global network</option>${countryOptions(networkFilter.country)}</select></label><label>Connection type<select data-network="type">${options([['all','All evidence types'],['relationship','Diplomatic relationships'],...COALITIONS.map(x=>[x,x.replaceAll('_',' ')])],networkFilter.type)}</select></label><label class="check"><input type="checkbox" data-network="connected" ${networkFilter.connected?'checked':''}> Hide unrelated countries</label><label class="check"><input type="checkbox" data-network="tentative" ${networkFilter.tentative?'checked':''}> Include tentative</label></div><svg class="network" viewBox="0 0 940 530" role="img" aria-label="Directional diplomatic network"><defs>${Object.entries(CATEGORIES).map(([k,v])=>`<marker id="arrow-${k}" viewBox="0 0 10 10" refX="20" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${v[1]}"/></marker>`).join('')}</defs>${links.map(a=>{const p=positions.get(a.country),q=positions.get(a.target);return p&&q?`<line data-act="evidence" data-id="${esc(a.id)}" x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" stroke="${CATEGORIES[a.category][1]}" stroke-width="2" stroke-dasharray="${a.status==='approved'?'':'5 5'}" marker-end="url(#arrow-${a.category})"><title>${esc(nameOf(a.country))} → ${esc(nameOf(a.target))}: ${esc(a.interpretation)}</title></line>`:''}).join('')}${nodes.map(c=>{const p=positions.get(c.id);return `<g data-act="network-country" data-id="${c.id}" tabindex="0" role="button" aria-label="Focus ${esc(c.name)}"><circle cx="${p.x}" cy="${p.y}" r="${c.id===networkFilter.country?19:13}" fill="${c.id===networkFilter.country?'#2c6c5d':'#233a47'}"/><text x="${p.x}" y="${p.y+4}" text-anchor="middle" style="font-size:9px;pointer-events:none">${c.id}</text><text x="${p.x}" y="${p.y+33}" text-anchor="middle">${esc(c.name.length>22?c.id:c.name)}</text><title>${esc(c.name)}</title></g>`}).join('')}${!links.length?'<text x="470" y="250" text-anchor="middle" style="font-size:18px">No evidenced connections yet</text><text x="470" y="278" text-anchor="middle">Review a statement to add the first relationship.</text>':''}</svg><div class="legend">${legendHTML()}<span>Solid: approved · Dashed: tentative · Arrows: publishing → target</span></div><div class="network-help">Select a country to highlight its connections. Select an edge or an evidence card to inspect its source.</div></section><section class="panel spaced"><div class="panel-head"><h2>Connection evidence · ${links.length}</h2></div>${assessmentsHTML(links)}</section>`;}
function timelineView(){const items=[...state.events,...state.statements.filter(s=>!s.deleted).map(s=>({id:s.id,title:s.title,date:s.date,country:s.country,type:'Delegation statement',text:`${nameOf(s.country)} · ${s.week}`,act:'statement',ref:s.id})),...state.proposals.map(p=>({id:p.id,title:p.title,date:p.date,country:p.country,type:'Proposal / '+p.status,text:p.origin,act:'go-proposal',ref:p.id})),...eligible(state).map(a=>({id:a.id,title:`${nameOf(a.country)} → ${a.kind==='proposal'?state.proposals.find(p=>p.id===a.target)?.title:nameOf(a.target)}`,date:state.statements.find(s=>s.id===a.statementId)?.date,country:a.country,type:a.kind==='coalition'?'Confirmed cooperation evidence':a.resolvesConflict?'Reviewed position change':'Reviewed assessment',text:a.interpretation,act:'evidence',ref:a.id})),...state.votes.map(v=>({id:v.id,title:v.title,date:v.date,country:'',type:'Recorded vote',text:tally(v.ballots,v.type,v.qualified).outcome,act:'edit-vote',ref:v.id}))].filter(x=>(!timelineFilter.country||x.country===timelineFilter.country)&&(!timelineFilter.from||x.date>=timelineFilter.from)&&(!timelineFilter.to||x.date<=timelineFilter.to)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return heading('THE EVOLVING PICTURE','Diplomatic timeline','Fictional event dates are separate from real import and review timestamps.',button('＋ Add event','new-event','','primary'))+`<section class="panel"><div class="filters"><label>Country<select data-timeline="country"><option value="">All countries</option>${countryOptions(timelineFilter.country)}<option value="ECU" ${timelineFilter.country==='ECU'?'selected':''}>Ecuador (scenario)</option></select></label><label>From<input type="date" data-timeline="from" value="${timelineFilter.from}"></label><label>Through<input type="date" data-timeline="to" value="${timelineFilter.to}"></label></div><div class="timeline spaced">${items.map(x=>`<article class="timeline-item"><small>${esc(x.date||'DATE NOT ENTERED')} · <span class="badge ${x.type==='Official scenario'?'warn':''}">${esc(x.type)}</span></small><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${x.act?button('View underlying record →',x.act,x.ref,'small quiet'):`${button('View source / event','view-event',x.id,'small quiet')}<small>${esc(x.source)}</small>`}</article>`).join('')||empty('No events match','Adjust your date or country filters.')}</div></section>`;}
function eventForm(){modal('Add a simulation development',`<form id="event-form"><div class="form-grid"><label class="full">Event title<input name="title" required maxlength="300"></label><label>Fictional event date<input type="date" name="date" required value="2050-11-01"></label><label>Country<select name="country"><option value="">Committee-wide</option>${countryOptions('')}<option value="ECU">Ecuador</option></select></label><label>Source type<select name="type">${options(['Official scenario update','Negotiation note','Delegation claim','Personal assessment','Crisis event'].map(x=>[x,x]),'Negotiation note')}</select></label><label>Source reference<input name="source" required placeholder="Document, page, author or meeting"></label><label class="full">Details<textarea name="text" required rows="5"></textarea></label></div><div class="form-actions"><button class="primary">Save event</button></div></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));await mutate('Create event',f.title,d=>d.events.push({...f,id:uid(),createdAt:now()}));closeModal();};}
function settingsView(){return heading('WORKSPACE CONTROLS','Settings','AI access, preferences, and portable backups.')+`<div class="panel-grid"><section class="panel pad"><span class="eyebrow">AI ANALYSIS</span><h2 class="spaced">Connect your secure endpoint</h2><p class="muted">AI runs through the same-origin server. Provider keys and the model are configured on the server, never in your browser database.</p><label>Owner access token<input id="owner-token" type="password" autocomplete="off" placeholder="Server OWNER_TOKEN — kept in memory only" value="${esc(ownerToken)}"></label><div class="actions spaced">${button('Use token for this session','set-token','','primary')}${button('Clear token','clear-token')}</div><p class="subtitle spaced">${ownerToken?'Session token set. It is cleared on refresh.':'No session token set. Manual entry and classification work without AI.'}</p><small class="spaced">Analysis sends the selected statement, up to 8 prior statements from that delegation, and proposal definitions to Google Gemini. Your original text stays in IndexedDB.</small></section><section class="panel pad"><span class="eyebrow">DATA & PORTABILITY</span><h2 class="spaced">Your archive, under your control</h2><p class="muted">Data is stored in this browser on this device. Use the same local URL and port to keep the same database. Export a backup before changing devices, browsers, or origins.</p><div class="actions">${button('Export full backup','backup','','primary')}${button('Restore JSON backup','restore')}</div><p class="subtitle spaced">${state.statements.length} statements · ${state.assessments.length} assessments · ${state.audit.length} audit entries</p><small class="spaced">Restore validates all records before a single atomic replacement. Export a backup first; restoration replaces this workspace.</small></section><section class="panel pad"><span class="eyebrow">IMPORT TEMPLATES</span><h2 class="spaced">Bring in a full week</h2><p class="muted">Bulk import supports JSON, quoted multiline CSV, TXT, and text-based PDFs. Review and assign each delegation before saving.</p><div class="actions">${button('Download CSV template','template-csv')}${button('Download JSON template','template-json')}${button('Open bulk importer','bulk-import')}</div></section><section class="panel pad"><span class="eyebrow">PROVENANCE & RULES</span><h2 class="spaced">Built for CPM 2050</h2><p class="muted">Scenario: <em>2050 — Ascenseur en panne</em>, POL5510, pp. 4, 11–13. Procedures: articles 2, 16–20. No 2026 political relationships are seeded. Geography uses Natural Earth reference boundaries, not inferred 2050 territorial changes.</p><div class="actions">${button('View audit history','audit')}${button('Export all statements CSV','statements-csv')}</div></section></div>`;}
function bulkImport(){bulkRows=[];modal('Import weekly statements',`<div class="notice">Upload several TXT/PDF files or one JSON/CSV file. Every record is editable before import. If a PDF includes several delegations, split its text into separate rows and assign each one.</div><label class="file-drop">Choose files<input type="file" id="bulk-files" accept=".txt,.pdf,.json,.csv" multiple></label><div id="bulk-status" class="form-status"></div><div id="bulk-editor"></div><div class="actions spaced">${button('Add blank row','bulk-add')}${button('Import reviewed records','bulk-save','','primary')}</div>`);$('#bulk-files').onchange=async e=>{try{$('#bulk-status').textContent='Reading documents…';for(const f of e.target.files){bulkRows.push(...await parseImport(f));if(bulkRows.length>200)throw Error('Maximum 200 rows per import.');}renderBulk();$('#bulk-status').textContent=`${bulkRows.length} extracted records. Review country assignments and text before importing.`;}catch(e){$('#bulk-status').textContent=e.message;}};}
function collectBulk(){for(const el of $$('[data-bulk-row]')){const i=Number(el.dataset.bulkRow);for(const input of $$('[data-field]',el))bulkRows[i][input.dataset.field]=input.value;}}
function renderBulk(){$('#bulk-editor').innerHTML=bulkRows.map((s,i)=>`<div class="review-card spaced" data-bulk-row="${i}"><h3>Record ${i+1}</h3><div class="form-grid"><label>Delegation<select data-field="country"><option value="">Assign delegation…</option>${countryOptions(s.country)}</select></label><label>Week<input data-field="week" value="${esc(s.week)}"></label><label>Date<input data-field="date" type="date" value="${esc(s.date)}"></label><label>Title<input data-field="title" value="${esc(s.title)}"></label><label class="full">Statement text<textarea data-field="text" rows="5">${esc(s.text)}</textarea></label><label class="full">Source URL<input data-field="url" value="${esc(s.url)}"></label></div><div class="actions spaced">${button('Duplicate to split text','bulk-split',i,'small')}${button('Remove row','bulk-remove',i,'small danger')}</div></div>`).join('');}
async function render(){const version=++renderVersion;if(activeMap){mapView={center:activeMap.getCenter(),zoom:activeMap.getZoom()};activeMap.remove();activeMap=null;}const [route='overview',id]=location.hash.slice(1).split('/');const mainRoute=route==='country'?'countries':route==='proposal'?'proposals':route;$('#nav').innerHTML=navItems.map(([key,icon,label])=>`<a href="#${key}" class="${key===mainRoute?'active':''}" ${key===mainRoute?'aria-current="page"':''} title="${label}"><span class="icon">${icon}</span><span class="nav-label">${label}</span></a>`).join('');$('#breadcrumb').textContent=navItems.find(n=>n[0]===mainRoute)?.[2]||'Overview';const views={overview,map:()=>heading('INTERACTIVE WORLD ATLAS','Read the diplomatic landscape.','Select a delegation, change perspective, and inspect the evidence behind every color.')+mapSection(true),countries:countriesView,country:()=>profile(id),statements:statementsView,proposals:proposalsView,proposal:()=>proposalView(id),alliances:networkView,timeline:timelineView,settings:settingsView};$('#main').innerHTML=(views[route]||overview)();const mapEl=$('#world-map');if(mapEl){try{const map=await mountMap(mapEl,state,{...filters,mapView},(country,name)=>{filters.selected=country||name;filters.selectedName=name;render();},id=>showEvidence(id));if(version===renderVersion)activeMap=map;else map?.remove();}catch(e){if(mapEl.isConnected)mapEl.innerHTML=`<div class="empty error-inline">${esc(e.message)}</div>`;}}}
function showEvidence(id){const a=state.assessments.find(x=>x.id===id);if(!a)return;const s=state.statements.find(x=>x.id===a.statementId);modal('Evidence & classification',`<p>${esc(nameOf(a.country))} → ${esc(a.kind==='proposal'?state.proposals.find(p=>p.id===a.target)?.title:nameOf(a.target))}</p>${evidenceValid(a,state)?reviewCard(a):`<p class="notice warn">Historical record. Its source was revised or deleted; this assessment no longer colors the map.</p>${assessmentsHTML([a])}`}<p class="muted">Source: ${esc(s?.title)} · ${esc(s?.date)} · statement ${esc(a.statementId)}</p>${s&&!s.deleted?button('Read complete source','statement',s.id):''}`);}
async function handleAction(act,id,el){switch(act){case 'new-statement':statementForm('',id||'GBR');break;case 'statement':showStatement(id);break;case 'edit-statement':statementForm(id);break;case 'analyze':await analyze(id);break;case 'manual':manualForm(id);break;case 'evidence':showEvidence(id);break;case 'save-review':{const card=el.closest('[data-review]'),fields=Object.fromEntries($$('[data-field]',card).map(x=>[x.dataset.field,x.type==='checkbox'?x.checked:x.value]));await mutate('Review classification',id,d=>{const a=d.assessments.find(x=>x.id===id);if(!evidenceValid(a,d))throw Error('Source changed; review the current revision.');audit(d,'Previous classification',a.statementId,a);Object.assign(a,fields,{locked:fields.locked&&fields.status==='approved',reviewedAt:now(),reviewedBy:'owner'});});toast('Review saved. Map updated.');break;}case 'save-summary':{const lines=$('#summary-edit').value.split('\n').map(x=>x.trim()).filter(Boolean);if(lines.length<3||lines.length>4||lines.some(x=>x.length>700))throw Error('Use exactly 3 or 4 concise, nonempty lines.');await mutate('Review summary',id,d=>{const s=d.statements.find(x=>x.id===id);const a=d.analyses.filter(x=>x.statementId===id&&x.sourceRevision===s.revision).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];if(a)a.reviewed=true;d.analyses.push({...a,id:uid(),statementId:id,country:s.country,sourceRevision:s.revision,summary:lines,createdAt:now(),origin:a?.origin||'manual',model:a?.model||'manual',reviewed:true,summaryEdited:true});});showStatement(id);toast('Reviewed summary saved.');break;}case 'approve-all':await mutate('Approve all current classifications',id,d=>{for(const a of d.assessments.filter(x=>x.statementId===id&&x.status==='tentative'&&evidenceValid(x,d))){audit(d,'Previous classification',id,a);a.status='approved';a.reviewedAt=now();}});showStatement(id);toast('Classifications approved. Contradictions remain flagged for review.');break;case 'archive':await mutate('Toggle archive',id,d=>{const s=d.statements.find(x=>x.id===id);s.archived=!s.archived;});showStatement(id);break;case 'delete-statement':modal('Delete this statement?',`<p>Only this statement will be removed from active views. Its assessments will no longer affect the map. A retained audit record allows recovery from a full backup.</p>${button('Delete statement','confirm-delete',id,'danger')}`);break;case 'confirm-delete':await mutate('Delete statement',id,d=>{const s=d.statements.find(x=>x.id===id);audit(d,'Deleted source',id,s);s.deleted=true;s.updatedAt=now();});closeModal();toast('Statement removed; unrelated records preserved.');break;case 'close-panel':filters.selected='';await render();break;case 'countries-csv':download('delegations.csv',toCSV(COUNTRIES.map(c=>({...c,orientation:resolve(state,c.id,'relationship',filters.perspective).category,statements:countryStatements(c.id).length})),['id','name','orientation','statements']),'text/csv');break;case 'statements-csv':download('statements.csv',toCSV(filteredStatements(),['country','week','date','title','text','url','notes']),'text/csv');break;case 'country-export':{const statements=countryStatements(id),ids=new Set(statements.map(s=>s.id));download(`country-${id}.json`,{format:'country-records',country:COUNTRIES.find(c=>c.id===id),statements,analyses:state.analyses.filter(a=>ids.has(a.statementId)),assessments:state.assessments.filter(a=>ids.has(a.statementId))});break;}case 'new-proposal':proposalForm();break;case 'edit-proposal':proposalForm(id);break;case 'go-proposal':closeModal();location.hash=`proposal/${id}`;break;case 'proposal-map':filters.mode='proposal';filters.proposal=id;location.hash='map';break;case 'new-vote':voteForm(id);break;case 'edit-vote':voteForm(state.votes.find(v=>v.id===id).proposalId,id);break;case 'network-country':networkFilter.country=id;await render();break;case 'new-event':eventForm();break;case 'view-event':{const e=state.events.find(x=>x.id===id);modal(e.title,`<span class="badge">${esc(e.type)}</span><p>${esc(e.date)}</p><div class="source-text">${esc(e.text)}</div><p>Source: ${esc(e.source)}</p>`);break;}case 'set-token':{const candidate=$('#owner-token').value.trim();if(candidate&&candidate.length<32)throw Error('Owner tokens must contain at least 32 characters.');ownerToken=candidate;}await render();toast('Owner token held in session memory.');break;case 'clear-token':ownerToken='';await render();break;case 'backup':download('DiplomaticAtlas-backup-'+new Date().toISOString().slice(0,10)+'.json',backup(state));break;case 'restore':{modal('Restore a full backup',`<p class="notice warn">Restoration replaces all local records. Export your current workspace first.</p>${button('Export current backup','backup')}<label class="file-drop spaced">Choose backup JSON<input id="restore-file" type="file" accept=".json"></label><div id="restore-preview" class="spaced"></div>`);$('#restore-file').onchange=async e=>{try{const file=e.target.files[0];if(file.size>30*1024*1024)throw Error('Backup limit: 30 MB.');const data=validateBackup(JSON.parse(await file.text()));$('#restore-preview').innerHTML=`<p>Validated: ${data.statements.length} statements, ${data.assessments.length} assessments and ${data.proposals.length} proposals.</p><button id="confirm-restore" class="primary">Replace workspace with this backup</button>`;$('#confirm-restore').onclick=async()=>{await mutate('Restore backup','workspace',d=>{for(const key of Object.keys(d))delete d[key];Object.assign(d,data);if(!d.settings.length)d.settings=[{id:'preferences',initialized:true,language:'English'}];});closeModal();toast('Backup restored.');};}catch(e){$('#restore-preview').textContent=e.message;}};break;}case 'template-csv':download('statement-import-template.csv','country,week,date,title,text,url,notes\r\n','text/csv');break;case 'template-json':download('statement-import-template.json',[{country:'GBR',week:'Week 1',date:'2050-11-01',title:'REPLACE WITH ACTUAL TITLE',text:'REPLACE WITH ORIGINAL STATEMENT',url:'',notes:''}]);break;case 'audit':modal('Audit history',state.audit.length?state.audit.slice().reverse().map(a=>`<div class="record"><h3>${esc(a.action)}</h3><small>${esc(a.at)} · ${esc(a.entity)}</small>${a.before?`<details><summary>Previous record</summary><div class="source-text">${esc(JSON.stringify(a.before,null,2))}</div></details>`:''}</div>`).join(''):empty('No changes yet','An audit trail is created as you work.'));break;case 'bulk-import':bulkImport();break;case 'bulk-add':collectBulk();bulkRows.push({country:'',week:'Week 1',date:'2050-11-01',title:'',text:'',url:'',notes:''});renderBulk();break;case 'bulk-split':collectBulk();bulkRows.splice(Number(id)+1,0,{...bulkRows[Number(id)],country:''});renderBulk();break;case 'bulk-remove':collectBulk();bulkRows.splice(Number(id),1);renderBulk();break;case 'bulk-save':{collectBulk();validateImport(bulkRows);if(!bulkRows.length)throw Error('Add at least one record.');let added=0,duplicates=0;await mutate('Bulk statement import','workspace',d=>{for(const s of bulkRows){if(d.statements.some(x=>!x.deleted&&x.country===s.country&&x.date===s.date&&x.week===s.week&&x.title===s.title&&x.text===s.text)){duplicates++;continue;}d.statements.push({...s,id:uid(),revision:1,createdAt:now(),updatedAt:now(),archived:false,deleted:false});added++;}});closeModal();location.hash='statements';toast(`${added} statements imported; ${duplicates} exact duplicates skipped.`);break;}}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-act],[data-sort]');if(!target)return;try{if(target.dataset.sort){const s=sort[target.dataset.sort];s.dir=s.key===target.dataset.key?-s.dir:1;s.key=target.dataset.key;await render();}else await handleAction(target.dataset.act,target.dataset.id,target);}catch(error){toast(error.message,true);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-act]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',async e=>{const x=e.target;const groups=[['map',filters],['statementFilter',statementFilter],['countryFilter',countryFilter],['network',networkFilter],['timeline',timelineFilter]];for(const [attr,obj] of groups){if(x.dataset[attr]){obj[x.dataset[attr]]=x.type==='checkbox'?x.checked:x.value;await render();break;}}});
window.addEventListener('hashchange',()=>{closeModal();render();});
try{state=await openDB();await render();}catch(e){$('#main').innerHTML=`<div class="notice error">Unable to open the local database: ${esc(e.message)}. Enable IndexedDB and use an HTTP server, not a file:// URL.</div>`;}
